#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    /* If no argument is supplied, the original program prints BALANCED. */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);
    /* Use a stack sized to the input length – the worst case is all opening brackets. */
    char *stack = malloc(len + 1);
    if (!stack) {
        perror("malloc");
        return 1;
    }
    size_t top = 0;
    int balanced = 1; // assume balanced until a mismatch is found

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                // push opening bracket
                stack[top++] = c;
                break;
            case ')':
            case ']':
            case '}': {
                if (top == 0) { // nothing to match
                    balanced = 0;
                    break;
                }
                char open = stack[--top]; // pop
                if ((c == ')' && open != '(') ||
                    (c == ']' && open != '[') ||
                    (c == '}' && open != '{')) {
                    balanced = 0;
                }
                break;
            }
            default:
                // ignore any other characters
                break;
        }
    }

    if (top != 0) {
        balanced = 0; // leftover opening brackets
    }

    puts(balanced ? "BALANCED" : "UNBALANCED");
    free(stack);
    return 0;
}
